(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8 + Math.cos((x-y)*0.012-t*0.18)*6;
  const w2y = Math.cos((x-y)*0.01-t*0.17)*8 + Math.sin((x+y)*0.011+t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 0.8],
    [340+Math.cos(t*0.45)*100, 150+Math.sin(t*0.6)*55, 0.09, 1.8, 1.0],
    [240+Math.sin(t*0.28+2)*130, 110+Math.cos(t*0.42+1)*80, 0.055, 2.4, 0.9],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.5+3)*55, 0.11, 1.6, 0.7],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*65, 0.065, 2.7, 1.1],
    [200+Math.cos(t*0.32+5)*110, 210+Math.sin(t*0.48)*70, 0.085, 2.0, 0.85],
    [300+Math.sin(t*0.55+3)*70, 30+Math.cos(t*0.65+1)*40, 0.1, 1.9, 0.95],
    [60+Math.cos(t*0.42+2)*60, 130+Math.sin(t*0.38+4)*50, 0.07, 2.5, 0.75]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att = w/(1+d*0.003);
    aS += Math.sin(d*f-t*sp)*att;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.8)*att;
    cS += Math.sin(d*f*1.3-t*sp*0.4+3.1)*att*0.4;
  }
  aS/=8; iS/=8; cS/=8;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.06+t*1.4)*Math.sin(sy*0.055-t*1.1)*0.3;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.05);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const nx = Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.4);
  const ny = Math.sin(sy*0.08+Math.cos(sx*0.06-t)*2-t*0.35);
  const organic = (nx+ny)*0.25;
  const react = Math.tanh((aS-iS*0.65+bg*0.25+spiral+organic+cS*0.3)*2.0);
  const cellA = Math.sin(sx*0.13)*Math.sin(sy*0.13);
  const cellB = Math.sin((sx+sy)*0.09+t*0.8)*Math.sin((sx-sy)*0.11-t*0.6);
  const cell = Math.tanh((cellA+cellB*0.7)*1.8)*0.25;
  const edge = 1.0-Math.abs(react)**8*0.3;
  const glow = Math.exp(-Math.abs(react)*3)*0.15;
  const blend = react*0.65+cell*0.2+glow;
  const v = blend*0.5+0.5;
  const hueShift = Math.sin(t*0.15)*0.08+Math.sin(dist*0.008-t*0.2)*0.06;
  const pal = [
    [5,12,52],[10,35,85],[12,68,105],[18,110,125],
    [35,155,135],[120,185,95],[210,195,60],
    [225,145,55],[200,85,65],[155,45,70],[90,22,60],[40,12,48],[5,12,52]
  ];
  const sv = Math.max(0,Math.min(1,v+hueShift));
  const idx = sv*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(react*Math.PI)*0.18;
  const ef = Math.abs(react)>0.65?1.12:1.0;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*ef*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*ef*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*ef*edge)|0
  ];
}
